// The users table's own user_id column is unused; the canonical internal id is the row id,
// which is what user_jobs/user_learning reference as user_id (stringified).
const users = $('Get Users').all().map(i => i.json)
  .filter(u => u && (u.id ?? u.user_id) != null)
  .map(u => ({ ...u, user_id: String(u.id ?? u.user_id) }));
const jobs = $('Get All User Jobs').all().map(i => i.json)
  .filter(r => r && r.user_id != null)
  .map(r => ({ ...r, user_id: String(r.user_id) }));

// One-user mode (started via "When called (one user)"): build only that user's course.
let onlyUserId = null;
try { const c = $('Course check').first().json; if (c && c.go) onlyUserId = String(c.user_row_id); } catch (e) {}

function parseArr(v) { if (v === null || v === undefined || v === '') return []; if (Array.isArray(v)) return v; try { const p = JSON.parse(v); return Array.isArray(p) ? p : []; } catch (e) { return []; } }
function slug(s) { return String(s || '').toLowerCase().trim().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 60); }

const MAX_SKILLS = 20;
const jobsByUser = {};
for (const j of jobs) { (jobsByUser[j.user_id] = jobsByUser[j.user_id] || []).push(j); }

const out = [];
for (const u of users) {
  if (onlyUserId && u.user_id !== onlyUserId) continue;
  const roles = parseArr(u.target_roles_json).map(r => String(r).trim()).filter(Boolean);
  if (roles.length === 0) continue;
  const userJobs = (jobsByUser[u.user_id] || []).filter(j => j.hidden !== true && j.prep_status === 'ready');
  if (userJobs.length === 0) continue;

  const skillMap = {};      // slug -> { skill, count, rank, whys[], jobIds[] }
  const courseRes = {};     // url -> { title, url, why }
  const practiceRes = {};   // url -> { title, url, type }
  const jobIds = new Set();

  for (const j of userJobs) {
    jobIds.add(j.job_id);
    parseArr(j.prep_skill_gaps_json).forEach((g, pos) => {
      const name = g && (g.skill || g.name);
      if (!name) return;
      const k = slug(name);
      if (!k) return;
      const e = skillMap[k] || (skillMap[k] = { skill: name, count: 0, rank: pos, whys: [], jobIds: [] });
      e.count++;
      e.rank = Math.min(e.rank, pos); // position of this gap in a job's list (0 = that job's top gap)
      if (g.why) e.whys.push(g.why);
      e.jobIds.push(j.job_id);
    });
    for (const c of parseArr(j.prep_courses_json)) {
      if (c && c.url && !courseRes[c.url]) courseRes[c.url] = { title: c.title || c.url, url: c.url, why: c.why || '' };
    }
    for (const p of parseArr(j.prep_practice_json)) {
      if (p && p.url && !practiceRes[p.url]) practiceRes[p.url] = { title: p.title || p.url, url: p.url, type: p.type || 'article' };
    }
  }

  // Most frequent first; ties broken by per-job rank so every job's top gaps are included before anyone's 3rd/4th gap.
  const skills = Object.values(skillMap).sort((a, b) => (b.count - a.count) || (a.rank - b.rank)).slice(0, MAX_SKILLS);
  if (skills.length === 0) continue;

  for (const role of roles) {
    out.push({ json: {
      user_id: String(u.user_id),
      auth_user_id: u.auth_user_id,
      role: role,
      // Per-user course: one course per (user, target role). Includes users.id so courses are never shared.
      course_id: 'course_' + u.user_id + '_' + slug(role),
      skills: skills.map(s => ({ skill: s.skill, count: s.count, why: (s.whys[0] || ''), job_ids: Array.from(new Set(s.jobIds)) })),
      course_resources: Object.values(courseRes).slice(0, 25),
      practice_resources: Object.values(practiceRes).slice(0, 25),
      job_ids: Array.from(jobIds),
    } });
  }
}
return out;

const items = $('Prepare All').all().map(i => i.json);
const byId = {};
for (const it of items) {
  if (!it.course_id) continue;
  if (!byId[it.course_id]) {
    byId[it.course_id] = {
      course_id: it.course_id,
      role: it.role,
      name: it.course_name,
      description: it.course_description,
      jobs_analyzed: it.jobs_analyzed || 0,
      skills_snapshot_json: JSON.stringify(it.skills_snapshot || []),
      now: it.now,
    };
  } else {
    byId[it.course_id].jobs_analyzed = Math.max(byId[it.course_id].jobs_analyzed, it.jobs_analyzed || 0);
  }
}
return Object.values(byId).map(json => ({ json }));

const items = $('Prepare All').all().map(i => i.json);
const byId = {};
for (const it of items) {
  for (const m of (it.modules || [])) {
    if (!m.module_id) continue;
    if (!byId[m.module_id]) {
      byId[m.module_id] = {
        module_id: m.module_id,
        course_id: m.course_id,
        title: m.title,
        skill_name: m.skill_name,
        description: m.description,
        content: m.content,
        resources_json: JSON.stringify(m.resources || []),
        importance_score: m.importance_score || 0,
        market_demand_percent: m.market_demand_percent || 0,
        trend_percent: m.trend_percent || 0,
        order_index: m.order_index || 0,
        now: it.now,
      };
    }
  }
}
return Object.values(byId).map(json => ({ json }));

const items = $('Prepare All').all().map(i => i.json);
const out = [];
const seen = new Set();
for (const it of items) {
  for (const m of (it.modules || [])) {
    if (!m.module_id) continue;
    const key = it.user_id + '::' + m.module_id;
    if (seen.has(key)) continue;
    seen.add(key);
    // Per-module jobs: only the jobs whose skill gaps this module covers (fallback: all of the user's jobs)
    const moduleJobs = (Array.isArray(m.job_ids) && m.job_ids.length) ? m.job_ids : (it.job_ids || []);
    out.push({ json: {
      user_id: it.user_id,
      course_id: it.course_id,
      module_id: m.module_id,
      learning_id: 'learn_' + it.user_id + '_' + m.module_id,
      priority_score: m.importance_score || 0,
      reason: m.skill_name ? ('Skill gap: ' + m.skill_name) : '',
      related_job_ids_json: JSON.stringify(moduleJobs),
      now: it.now,
    } });
  }
}
return out;

const courses = $('Prepare All').all().map(i => i.json);
const ok = courses.filter(c => c.course_id);
const courseIds = [...new Set(ok.map(c => c.course_id))];
const skipped = courses.filter(c => !c.course_id).map(c => ({ user_id: c.user_id, role: c.role, error: c.error }));
return [{ json: { success: true, roles_processed: courses.length, unique_courses: courseIds.length, course_ids: courseIds, skipped } }];

