const src = $('Loop Roles').item.json;
const res = $json;
let text = '';
if (Array.isArray(res.content)) text = res.content.filter(c => c.type === 'text').map(c => c.text).join('\n');
else text = res.text || res.merged_response || '';

const m = text.match(/\{[\s\S]*\}/);
let parsed;
try { parsed = JSON.parse(m ? m[0] : text); }
catch (e) {
  // Truncated / invalid model output: skip this user's course this run instead of failing the run for every user
  return { json: { user_id: src.user_id, role: src.role, course_id: null, skipped: true, error: 'Course JSON invalid: ' + String(text).slice(0, 300), modules: [], job_ids: [] } };
}

function slug(s) { return String(s || '').toLowerCase().trim().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 60); }
const nowIso = new Date().toISOString();

// skill slug -> job_ids that listed this skill gap (per-user, from Build Role Aggregates)
const jobsBySkill = {};
for (const s of (src.skills || [])) {
  const k = slug(s.skill);
  if (k) jobsBySkill[k] = Array.from(new Set([...(jobsBySkill[k] || []), ...(s.job_ids || [])]));
}
function moduleJobIds(mm) {
  const names = [].concat(Array.isArray(mm.source_skills) ? mm.source_skills : [], mm.skill_name ? [mm.skill_name] : []);
  const ids = new Set();
  for (const n of names) {
    const k = slug(n);
    if (!k) continue;
    if (jobsBySkill[k]) { jobsBySkill[k].forEach(id => ids.add(id)); continue; }
    // fuzzy fallback: slug containment either way
    for (const sk of Object.keys(jobsBySkill)) {
      if (sk.includes(k) || k.includes(sk)) jobsBySkill[sk].forEach(id => ids.add(id));
    }
  }
  return ids.size ? Array.from(ids) : (src.job_ids || []);
}

const usedSlugs = {};
const modules = (parsed.modules || []).slice(0, 8).map((mm, idx) => {
  let base = slug(mm.skill_name || mm.title || ('module_' + idx)) || ('module_' + idx);
  let key = base;
  let n = 2;
  while (usedSlugs[key]) { key = base + '_' + n; n++; }
  usedSlugs[key] = true;
  const resources = Array.isArray(mm.resources) ? mm.resources.filter(r => r && r.url) : [];
  return {
    module_id: src.course_id + '_' + key,
    course_id: src.course_id,
    title: mm.title || mm.skill_name || ('Module ' + (idx + 1)),
    skill_name: mm.skill_name || '',
    description: mm.description || '',
    content: mm.content || '',
    resources: resources,
    importance_score: Number(mm.importance_score) || 0,
    market_demand_percent: Number(mm.market_demand_percent) || 0,
    trend_percent: Number(mm.trend_percent) || 0,
    order_index: idx,
    job_ids: moduleJobIds(mm),
  };
});

return { json: {
  user_id: src.user_id,
  auth_user_id: src.auth_user_id,
  role: src.role,
  course_id: src.course_id,
  course_name: parsed.course_name || parsed.name || src.role,
  course_description: parsed.course_description || parsed.description || '',
  jobs_analyzed: (src.job_ids || []).length,
  skills_snapshot: (src.skills || []).map(s => s.skill),
  job_ids: src.job_ids || [],
  modules: modules,
  now: nowIso,
} };

// Modules of the courses regenerated in THIS run that the model no longer produced.
// Modules with any user progress are kept so nobody loses completed work.
const fresh = $('Prepare All').all().map(i => i.json);
const courseIds = new Set(fresh.map(c => c.course_id).filter(Boolean));
const keep = new Set(fresh.flatMap(c => (c.modules || []).map(m => m.module_id)));
const learning = $('Get Learning For Prune').all().map(i => i.json).filter(r => r && r.module_id);
const touched = new Set(learning
  .filter(r => (Number(r.progress_percent) || 0) > 0 || (r.status && r.status !== 'not_started'))
  .map(r => r.module_id));
const stale = $('Get Modules For Prune').all().map(i => i.json)
  .filter(m => m && m.module_id && courseIds.has(m.course_id) && !keep.has(m.module_id) && !touched.has(m.module_id));
// Always emit at least one item so the rest of the flow continues; the placeholder matches no rows.
if (stale.length === 0) return [{ json: { course_id: '__none__', module_id: '__none__', placeholder: true } }];
return stale.map(m => ({ json: { course_id: m.course_id, module_id: m.module_id } }));

const w = $('Regenerate (Lovable)').first().json;
const id = (w.query && w.query.auth_user_id) || (w.body && w.body.auth_user_id);
return [{ json: {
  success: true,
  status: 'started',
  auth_user_id: id,
  message: 'Job search, interview prep, referrals and the course are being (re)built for this user. Poll /webhook/courses (and /webhook/jobs, /webhook/referrals); the course appears when every job has its prep plan, usually within 5-15 minutes.'
} }];

const t = $('When called (one user)').first().json;
const id = String(t.auth_user_id || '').trim();
if (!id) throw new Error('auth_user_id is required');
return [{ json: { auth_user_id: id, force: t.force === true } }];

// Decides whether this user's course can be (re)built now.
// preparing   = some jobs still have no interview-prep plan (get_materials calls this again when it finishes)
// building    = all jobs prepared and (force, or prep newer than the last course build)
// up_to_date  = nothing new since the last course build
const inp = $('One user input').first().json;
const u = $('Get this user').first().json || {};
if (u.id === undefined || u.id === null) return [{ json: { go: false, status: 'user_not_found', auth_user_id: inp.auth_user_id } }];
const rows = $('Get this user jobs').all().map(i => i.json).filter(r => r && r.job_id && r.hidden !== true);
const ready = rows.filter(r => r.prep_status === 'ready');
const pending = rows.length - ready.length;
const newest = ready.reduce((m, r) => Math.max(m, r.prep_updated_at ? new Date(r.prep_updated_at).getTime() : 0), 0);
const last = u.last_course_refresh_at ? new Date(u.last_course_refresh_at).getTime() : 0;
let go = false, status;
if (!rows.length) status = 'no_jobs';
else if (pending > 0) status = 'preparing';
else if (inp.force || !last || newest > last) { go = true; status = 'building'; }
else status = 'up_to_date';
return [{ json: { go, status, auth_user_id: inp.auth_user_id, user_row_id: u.id, jobs: rows.length, ready_jobs: ready.length, pending_jobs: pending } }];
